        window.parent.postMessage({ type:'braze-popup-ready', id:'bc-iam-1' }, '*');
      }
    } catch(_) {}
  }

  function cleanup(){
    cleanupFns.forEach(function(fn){ try{ fn(); } catch(_){} });
    cleanupFns = [];
  }

