    try{ console.warn('IAM init fail:', reason); } catch(_) {}
    cleanup();
    safeRemove();
  }

  function tryInit(){
    initAttempts++;
    root = document.getElementById('bc-iam-1');
    setBridgeIfPresentNow();

    if (!root){
      if (initAttempts < maxAttempts) { setTimeout(tryInit, 200); return; }
      hardFail('no-root');
      return;
    }

