<script>
(function(){
  'use strict';

  var initAttempts = 0, maxAttempts = 20;
  var cleanupFns = [];
  var isInitialized = false;
  var root = null;
  var bridge = null;
  var firedEverflow = false;

  window.addEventListener('ab.BridgeReady', function(){
    bridge = window.brazeBridge || window.appboyBridge || null;
  }, { once:true });

  function setBridgeIfPresentNow(){
    if (!bridge && (window.brazeBridge || window.appboyBridge)) {
      bridge = window.brazeBridge || window.appboyBridge;
    }
  }

  function stripQueryKeys(url, keys){
    try {
      if (typeof URL === 'function') {
        var u = new URL(url, window.location.href);
        keys.forEach(function(k){ u.searchParams.delete(k); });
        return u.toString();
      }
