<style>
/* System fonts only */
#bc-iam-1, #bc-iam-1 *{
  box-sizing:border-box;
  font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
}
#bc-iam-1{
  width:100%;
  display:grid;
  place-items:center;
  margin:0 !important;
  padding:0 !important;
  isolation:isolate;
}

/* Card styles */
#bc-iam-1 .card{
  position:relative;
  width:100%;
  max-width:420px;
  background:#fff;
  border:1px solid #e5e7eb;
  border-radius:10px;
  box-shadow:0 1px 2px rgba(16,24,40,.06), 0 1px 1px rgba(16,24,40,.04);
  padding:12px;
  color:#111;
  line-height:1.4;
  font-size:14px;
  font-weight:700;
  cursor:pointer; /* full-unit click affordance */
}
#bc-iam-1 .card:focus{
  outline:2px solid rgba(17, 24, 39, 0.35);
  outline-offset:3px;
}

/* Header */
#bc-iam-1 .header{
  display:flex;
  gap:10px;
  align-items:center;
  position:relative;
  z-index:2;
}
#bc-iam-1 .avatar{
  width:40px; height:40px;
  border-radius:999px;
  overflow:hidden;
  flex:0 0 40px;
  border:1px solid #e5e7eb;
  background:#fff;
}
#bc-iam-1 .avatar img{ width:100%; height:100%; object-fit:cover; display:block; }
#bc-iam-1 .headings{ display:flex; flex-direction:column; align-items:flex-start; }
#bc-iam-1 .brand{ font-size:16px; font-weight:700; text-align:left; }
#bc-iam-1 .meta-note{ font-size:12px; font-weight:400; color:#6b7280; margin-top:2px; text-align:left; }

/* Headline (NO clamping — show all text) */
#bc-iam-1 .headline{
  font-size:14px;
  font-weight:700;
  color:#111;
  margin:10px 2px 8px 2px;
  position:relative;
  z-index:2;
}
#bc-iam-1 .normal{ font-weight:400; }

/* Hero — UPDATED: flexible height, no black bars */
#bc-iam-1 .hero{
  margin:0;
  border-radius:6px;
  overflow:hidden;
  border:1px solid #e5e7eb;
  background:#fff;
  position:relative;
  z-index:2;
}
#bc-iam-1 .hero img{
  display:block;
  width:100%;
  height:auto;
  object-fit:contain;
  object-position:center;
}

/* Footer */
#bc-iam-1 .footer{
  margin-top:10px;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  position:relative;
  z-index:2;
}
#bc-iam-1 .cta{
  display:inline-block;
  padding:8px 14px;
  font-size:14px;
  font-weight:700;
  color:#fff;
  background:#004f88;
  border:1px solid #004f88;
  border-radius:8px;
  text-decoration:none;
  cursor:pointer;
  position:relative;
  z-index:5;
  transition:background 0.2s ease, border-color 0.2s ease;
}
#bc-iam-1 .cta:hover{ background:#3E9E3E; border-color:#3E9E3E; }

#bc-iam-1 .sponsor-note{
  margin-top:8px;
  font-size:11px;
  font-weight:400;
  color:#6b7280;
  text-align:center;
}

/* Desktop: wider card, NO fixed hero height */
@media (min-width: 720px){
  #bc-iam-1 .card{ max-width:720px; padding:16px; }
  /* Hero height is auto — shrink-wraps to image */
  #bc-iam-1 .hero img{
    width:100%;
    height:auto;
    object-fit:contain;
    object-position:center;
  }
}
