<script>
(function(){
  'use strict';

  var initAttempts = 0, maxAttempts = 20;
  var cleanupFns = [];
  var isInitialized = false;
  var root = null;
  var bridge = null;
  var firedEverflow = false;
  var navigated = false; // Guard against any double navigation

  window.addEventListener('ab.BridgeReady', function(){
    bridge = window.brazeBridge || window.appboyBridge || null;
  }, { once:true });

  function setBridgeIfPresentNow(){
    if (!bridge && (window.brazeBridge || window.appboyBridge)) {
      bridge = window.brazeBridge || window.appboyBridge;
    }
  }

  function stripQueryKeys(url, keys){
    try {
      if (typeof URL === 'function') {
        var u = new URL(url, window.location.href);
        keys.forEach(function(k){ u.searchParams.delete(k); });
        return u.toString();
      }
    } catch(_) {}
    try {
      var parts = url.split('#');
      var hash = parts.length > 1 ? ('#' + parts.slice(1).join('#')) : '';
      var baseAndQs = parts[0].split('?');
      if (baseAndQs.length < 2) return url;
      var base = baseAndQs[0];
      var qs = baseAndQs.slice(1).join('?');
      var kept = qs.split('&').filter(function(pair){
        var k = (pair.split('=')[0] || '').trim();
        return keys.indexOf(k) === -1;
      }).join('&');
      return base + (kept ? ('?' + kept) : '') + hash;
    } catch(_) {
      return url;
    }
  }

  function fireEverflowImpressionOnce(p){
    if (firedEverflow) return;
    firedEverflow = true;

    var base = '';
    try { base = String(root.getAttribute('data-ef-impression') || '').trim(); } catch(_) { base = ''; }
    if (!base) return;

    base = stripQueryKeys(base, ['sub1','sub2','sub3','sub4','_ts']);

    try {
      var sep = base.indexOf('?') >= 0 ? '&' : '?';
      var url = base + sep +
        'sub1=' + encodeURIComponent(p.adv) +
        '&sub2=' + encodeURIComponent(p.sec) +
        '&sub3=' + encodeURIComponent(p.src) +
        '&sub4=' + encodeURIComponent(p.placement) +
        '&_ts=' + Date.now();

      var img = new Image();
      img.referrerPolicy = 'no-referrer-when-downgrade';
      img.src = url;
    } catch(_) {}
  }

  function logEvent(name, payload){
    try{
      setBridgeIfPresentNow();
      if (bridge && typeof bridge.logCustomEvent === 'function') {
        bridge.logCustomEvent(name, payload);
        if (typeof bridge.requestImmediateDataFlush === 'function') {
          bridge.requestImmediateDataFlush();
        }
      } else if (window.braze && typeof window.braze.logCustomEvent === 'function') {
        window.braze.logCustomEvent(name, payload);
        if (typeof window.braze.requestImmediateDataFlush === 'function') {
          window.braze.requestImmediateDataFlush();
        }
      }
    } catch(_) {}
  }

  function logClickMetric(){
    try{
      setBridgeIfPresentNow();
      if (bridge && typeof bridge.logClick === 'function') {
        bridge.logClick('cta');
      }
    } catch(_) {}
  }

  function requestClose(){
    try{
      setBridgeIfPresentNow();
      if (bridge && typeof bridge.closeMessage === 'function') {
        bridge.closeMessage();
        return;
      }
    } catch(_) {}
    try{
      if (window.parent && window.parent !== window) {
        window.parent.postMessage({ type:'close-braze-popup', id:'bc-iam-1' }, '*');
      }
    } catch(_) {}
    safeRemove();
  }

  function safeRemove(){
    try{
      var el = document.getElementById('bc-iam-1');
      if (el) el.remove();
    } catch(_) {}
  }

  function initialize(rootEl){
    var props = {
      adv: String(rootEl.getAttribute('data-adv') || 'unknown'),
      sec: String(rootEl.getAttribute('data-sec') || 'general'),
      src: String(rootEl.getAttribute('data-src') || 'iam'),
      placement: String(rootEl.getAttribute('data-placement') || 'center_modal')
    };

    var ctaHref = String(rootEl.getAttribute('data-cta-href') || '').trim();

    // Keep CTA button href synced
    var ctaBtn = document.getElementById('cta-btn');
    if (ctaBtn && ctaHref) ctaBtn.setAttribute('href', ctaHref);

    fireEverflowImpressionOnce(props);
    logEvent('ad_impression', props);

    var card = document.getElementById('bc-card');
    if (card){
      var onCardClick = function(e){
        // FIXED v2: Check navigation guard FIRST before any logging
        if (navigated) return;

        // Check if user clicked directly on the CTA link
        var a = e && e.target && e.target.closest ? e.target.closest('a') : null;
        if (a && a.getAttribute('href')) {
          // Direct CTA click: log and let browser handle navigation
          navigated = true;
          logClickMetric();
          logEvent('ad_click', props);
          return;
        }

        // Non-CTA click: log then trigger CTA programmatically
        navigated = true;
        logClickMetric();
        logEvent('ad_click', props);

        // FIXED v2: Route through the real <a> element instead of window.open
        // This prevents double-navigation issues in iframe contexts
        var btn = document.getElementById('cta-btn');
        if (btn) {
          btn.click();
        }
      };

      var onCardKey = function(e){
        if (!e) return;
        // FIXED v2: Check navigation guard FIRST
        if (navigated) return;

        var key = e.key || e.code;
        if (key === 'Enter' || key === ' ' || key === 'Spacebar') {
          var a = e && e.target && e.target.closest ? e.target.closest('a') : null;

          if (a && a.getAttribute('href')) {
            // Direct CTA keyboard activation: log and let browser handle
            navigated = true;
            logClickMetric();
            logEvent('ad_click', props);
            return;
          }

          // Card keyboard activation: prevent default and trigger CTA
          e.preventDefault();
          navigated = true;
          logClickMetric();
          logEvent('ad_click', props);

          var btn = document.getElementById('cta-btn');
          if (btn) {
            btn.click();
          }
        }
      };

      card.addEventListener('click', onCardClick);
      card.addEventListener('keydown', onCardKey);
      cleanupFns.push(function(){
        card.removeEventListener('click', onCardClick);
        card.removeEventListener('keydown', onCardKey);
      });
    }

    var onEsc = function(e){ if (e && e.key === 'Escape') requestClose(); };
    document.addEventListener('keydown', onEsc);
    cleanupFns.push(function(){ document.removeEventListener('keydown', onEsc); });

    var onMsg = function(e){
      if (e && e.data && (e.data.type === 'close-braze-popup' || e.data === 'close')) {
        requestClose();
      }
    };
    window.addEventListener('message', onMsg);
    cleanupFns.push(function(){ window.removeEventListener('message', onMsg); });

    var observer = new MutationObserver(function(muts){
      for (var i=0;i<muts.length;i++){
        var r = muts[i].removedNodes;
        for (var j=0;j<r.length;j++){
          var node = r[j];
          if (node === rootEl || (node.contains && node.contains(rootEl))) {
            cleanup();
            observer.disconnect();
            return;
          }
        }
      }
    });
    if (rootEl.parentNode){
      observer.observe(rootEl.parentNode, { childList:true, subtree:true });
      cleanupFns.push(function(){ observer.disconnect(); });
    }

    try{
      if (window.parent && window.parent !== window) {
        window.parent.postMessage({ type:'braze-popup-ready', id:'bc-iam-1' }, '*');
      }
    } catch(_) {}
  }

  function cleanup(){
    cleanupFns.forEach(function(fn){ try{ fn(); } catch(_){} });
    cleanupFns = [];
  }

  function hardFail(reason){
    try{ console.warn('IAM init fail:', reason); } catch(_) {}
    cleanup();
    safeRemove();
  }

  function tryInit(){
    initAttempts++;
    root = document.getElementById('bc-iam-1');
    setBridgeIfPresentNow();

    if (!root){
      if (initAttempts < maxAttempts) { setTimeout(tryInit, 200); return; }
      hardFail('no-root');
      return;
    }

    initialize(root);
    isInitialized = true;
  }

  tryInit();

  setTimeout(function(){
    if (!isInitialized) hardFail('watchdog');
  }, 5000);
})();
